package com.tencent.weknora.security;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.time.*;import java.util.*;import java.util.stream.*;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.core.io.FileSystemResource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.init.ScriptUtils;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"weknora.jwt-secret=register-go-parity-secret","weknora.bridge.enabled=false","logging.level.root=WARN","debug=false"}) @AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class InvitationRegistrationGoParityTest {
 private static final Path DB;static{try{DB=Files.createTempFile("weknora-register-go-parity-",".db");DB.toFile().deleteOnExit();}catch(Exception e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry p){p.add("spring.datasource.url",()->"jdbc:sqlite:"+DB+"?busy_timeout=10000");p.add("spring.datasource.driver-class-name",()->"org.sqlite.JDBC");}
 @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired DataSource datasource;@Autowired ObjectMapper json;@Autowired AuthRepository repository;
 @BeforeAll void schema()throws Exception{try(var c=datasource.getConnection()){for(String script:List.of("000000_init.up.sql","000005_messages_attachments_and_invitation_fields.up.sql","000007_system_admin_and_settings.up.sql"))ScriptUtils.executeSqlScript(c,new FileSystemResource("../migrations/sqlite/"+script));}}
 @TestFactory Stream<DynamicTest> actualGoRegistrationStages()throws Exception{JsonNode fixture=json.readTree(Files.readString(Path.of("src/test/java/com/tencent/weknora/security/register-by-invite-golden.json")));List<DynamicTest> out=new ArrayList<>();fixture.fields().forEachRemaining(entry->out.add(DynamicTest.dynamicTest(entry.getKey(),()->run(entry.getKey(),entry.getValue()))));return out.stream();}
 private void run(String mode,JsonNode row)throws Exception{
  for(String table:List.of("tenant_invitations","audit_logs","auth_tokens","tenant_members","users","tenants","system_settings"))jdbc.update("DELETE FROM "+table);jdbc.update("INSERT INTO tenants(id,name,status,business) VALUES(7,'Workspace','active','test')");jdbc.update("INSERT INTO tenant_invitations(tenant_id,invitee_user_id,role,status,token,expires_at) VALUES(7,'','contributor','pending','shared-link-token',?)",repository.timestampParameter(mode.equals("expired")?Instant.now().minusSeconds(3600):Instant.now().plusSeconds(3600)));
  if(mode.equals("disabled")||mode.equals("invite-only"))jdbc.update("INSERT INTO system_settings(key,value,value_type,category,last_modified_by) VALUES('auth.registration_mode',?,'string','auth','owner')",json.writeValueAsString(mode.equals("disabled")?"disabled":"invite_only"));
  if(mode.equals("duplicate-email"))jdbc.update("INSERT INTO users(id,username,email,password_hash,is_active) VALUES('existing','existing','new@example.com','unused',true)");if(mode.equals("duplicate-username"))jdbc.update("INSERT INTO users(id,username,email,password_hash,is_active) VALUES('existing','tester','existing@example.com','unused',true)");
  List<String> triggers=new ArrayList<>();if(mode.equals("member-failure")||mode.equals("rollback-failure")){triggers.add("fail_member");jdbc.execute("CREATE TRIGGER fail_member BEFORE INSERT ON tenant_members BEGIN SELECT RAISE(ABORT,'oracle member failure'); END");}if(mode.equals("home-failure")){triggers.add("fail_home");jdbc.execute("CREATE TRIGGER fail_home BEFORE UPDATE ON users WHEN NEW.tenant_id=7 BEGIN SELECT RAISE(ABORT,'oracle home failure'); END");}if(mode.equals("rollback-failure")){triggers.add("fail_rollback");jdbc.execute("CREATE TRIGGER fail_rollback BEFORE UPDATE ON users WHEN COALESCE(NEW.tenant_id,0)=0 AND OLD.tenant_id=7 BEGIN SELECT RAISE(ABORT,'oracle rollback failure'); END");}if(mode.equals("access-token-failure")||mode.equals("refresh-token-failure")){triggers.add("fail_token");jdbc.execute("CREATE TRIGGER fail_token BEFORE INSERT ON auth_tokens WHEN NEW.token_type='"+(mode.equals("access-token-failure")?"access_token":"refresh_token")+"' BEGIN SELECT RAISE(ABORT,'oracle token failure'); END");}if(mode.equals("create-user-failure")){triggers.add("fail_create");jdbc.execute("CREATE TRIGGER fail_create BEFORE INSERT ON users BEGIN SELECT RAISE(ABORT,'oracle create failure'); END");}
  try{var response=mvc.perform(post("/api/v1/auth/register-by-invite").contentType("application/json").content(json.writeValueAsBytes(row.path("request")))).andReturn().getResponse();var body=json.readTree(response.getContentAsByteArray());Map<String,Object> actual=new LinkedHashMap<>();actual.put("status",response.getStatus());if(body.has("error")){actual.put("code",body.path("error").path("code").asInt());actual.put("message",body.path("error").path("message").asText());}else{actual.put("message",body.path("message").asText());Map<String,Object> profile=new LinkedHashMap<>();for(String key:List.of("username","email","tenant_id","is_active","can_access_all_tenants","is_system_admin","preferences"))profile.put(key,json.convertValue(body.path("user").path(key),Object.class));actual.put("profile",profile);actual.put("memberships",json.convertValue(body.path("memberships"),Object.class));}
   List<Map<String,Object>> users=new ArrayList<>();for(var user:jdbc.queryForList("SELECT * FROM users WHERE email='new@example.com'"))users.add(Map.of("username",AuthRepository.string(user,"username"),"email",AuthRepository.string(user,"email"),"tenant_id",AuthRepository.number(user,"tenant_id"),"active",AuthRepository.bool(user,"is_active"),"deleted",user.get("deleted_at")!=null));actual.put("users",users);actual.put("member_rows",jdbc.queryForList("SELECT tenant_id,role,status FROM tenant_members WHERE deleted_at IS NULL"));actual.put("token_rows",jdbc.queryForObject("SELECT COUNT(*) FROM auth_tokens",Integer.class));actual.put("accepted_count",jdbc.queryForObject("SELECT accepted_count FROM tenant_invitations",Integer.class));actual.put("audits",jdbc.queryForList("SELECT actor_user_id,actor_role,action,outcome FROM audit_logs ORDER BY id"));assertEquals(row.path("result"),json.readTree(json.writeValueAsBytes(actual)));
  }finally{for(String trigger:triggers)jdbc.execute("DROP TRIGGER "+trigger);}
 }
}
